/* Incident Clarity local-only review. No network calls or analytics. */
"use strict";

const $ = (id) => document.getElementById(id);
let pack;
let active = null;

function showError(message) {
  $("error").textContent = message;
  $("error").hidden = false;
}

function hashSeed(text) {
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function seededOrder(items, seedText) {
  const result = items.slice();
  let state = hashSeed(seedText) || 1;
  const random = () => {
    state += 0x6D2B79F5;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  for (let i = result.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

function storageKey(reviewer, policy) {
  return `incident-clarity:v1:${pack.pack_version}:${policy}:${reviewer}`;
}

function safeRecords(value) {
  if (!Array.isArray(value)) return [];
  return value.filter((r) => r && typeof r === "object" && typeof r.scenario_id === "string");
}

function currentRecords() {
  if (!active) return [];
  try {
    return safeRecords(JSON.parse(localStorage.getItem(storageKey(active.reviewer, active.policy)) || "[]"));
  } catch (_) {
    return [];
  }
}

function saveRecords(records) {
  localStorage.setItem(storageKey(active.reviewer, active.policy), JSON.stringify(records));
}

function renderCase() {
  const records = currentRecords();
  const remaining = active.order.filter((id) => !records.some((r) => r.scenario_id === id));
  if (remaining.length === 0) {
    renderComplete(records);
    return;
  }
  $("intro").hidden = true;
  $("complete").hidden = true;
  $("review").hidden = false;
  const scenario = pack.scenarios.find((s) => s.id === remaining[0]);
  const completed = records.length;
  $("progress").textContent = `${completed} saved · ${pack.scenarios.length - completed} remaining`;
  $("case-progress").max = pack.scenarios.length;
  $("case-progress").value = completed + 1;
  $("case-label").textContent = `${scenario.id} · FICTIONAL CASE`;
  $("case-title").textContent = scenario.title;
  $("case-facts").replaceChildren(...scenario.facts.map((fact) => {
    const li = document.createElement("li");
    li.textContent = fact;
    return li;
  }));
  $("response-form").reset();
  $("confidence").value = 3;
  $("confidence-output").value = "3";
  window.scrollTo({ top: 0, behavior: "auto" });
}

function renderComplete(records) {
  $("intro").hidden = true;
  $("review").hidden = true;
  $("complete").hidden = false;
  $("export-preview").textContent = records.map((r) => JSON.stringify(r)).join("\n");
  window.scrollTo({ top: 0, behavior: "auto" });
}

async function initialize() {
  try {
    const response = await fetch("scenarios-v0.1.json");
    if (!response.ok) throw new Error(`Pack request returned ${response.status}`);
    pack = await response.json();
    if (!Array.isArray(pack.scenarios) || !Array.isArray(pack.policies)) throw new Error("Invalid pack schema");
    $("policy").replaceChildren(...pack.policies.map((policy) => {
      const option = document.createElement("option");
      option.value = policy.id;
      option.textContent = policy.label;
      option.selected = policy.id === pack.default_policy_id;
      return option;
    }));
  } catch (error) {
    showError(`Could not load the local scenario pack: ${error.message}. If opening this file directly, use the hosted site or serve this directory with a local static server.`);
    $("start-form").querySelector("button").disabled = true;
  }
}

$("start-form").addEventListener("submit", (event) => {
  event.preventDefault();
  if (!pack) return;
  const reviewer = $("reviewer").value.trim();
  if (!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/.test(reviewer)) {
    showError("Use a 1–64 character pseudonym with letters, numbers, dots, dashes, or underscores only.");
    return;
  }
  const policy = $("policy").value;
  if (!pack.policies.some((p) => p.id === policy)) {
    showError("Choose a valid research prompt.");
    return;
  }
  active = { reviewer, policy, order: seededOrder(pack.scenarios.map((s) => s.id), `${pack.pack_version}:${reviewer}`) };
  $("policy-text").textContent = pack.policies.find((p) => p.id === policy).text;
  $("error").hidden = true;
  try {
    renderCase();
  } catch (error) {
    showError(`Browser storage is unavailable: ${error.message}. Enable local storage or use the Python review tool.`);
  }
});

$("confidence").addEventListener("input", () => { $("confidence-output").value = $("confidence").value; });

$("response-form").addEventListener("submit", (event) => {
  event.preventDefault();
  if (!active || !pack) return;
  const selected = document.querySelector('input[name="judgment"]:checked');
  if (!selected || !$("clock").value || !$("rationale").value.trim()) {
    showError("Select a judgment and clock value, and enter a brief rationale.");
    return;
  }
  const records = currentRecords();
  const remaining = active.order.filter((id) => !records.some((r) => r.scenario_id === id));
  const record = {
    schema_version: "1.0",
    pack_version: pack.pack_version,
    policy_id: active.policy,
    scenario_id: remaining[0],
    reviewer_id: active.reviewer,
    judgment: selected.value,
    clock_start: $("clock").value,
    confidence: Number($("confidence").value),
    decisive_phrase: $("decisive").value.trim(),
    rationale: $("rationale").value.trim(),
    missing_fact: $("missing").value.trim(),
    created_at: new Date().toISOString()
  };
  try {
    saveRecords(records.concat(record));
    $("error").hidden = true;
    renderCase();
  } catch (error) {
    showError(`Could not save this response: ${error.message}. Your current response has not been saved.`);
  }
});

$("save-exit").addEventListener("click", () => {
  $("review").hidden = true;
  $("intro").hidden = false;
  window.scrollTo({ top: 0, behavior: "auto" });
});

$("export").addEventListener("click", () => {
  const records = currentRecords();
  if (!records.length) return;
  const blob = new Blob([records.map((r) => JSON.stringify(r)).join("\n") + "\n"], { type: "application/x-ndjson" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `${active.reviewer}-${active.policy}-${pack.pack_version}.jsonl`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
});

$("back").addEventListener("click", () => {
  active = null;
  $("complete").hidden = true;
  $("intro").hidden = false;
  window.scrollTo({ top: 0, behavior: "auto" });
});

initialize();

